        if (page.body == null) throw new Error("missing_page_body");
        if (`/courses/${source.courseId}/pages/${page.url}` !== path)
          throw new Error("page_identity_mismatch");
        signal.throwIfAborted();
        if (
          !store
            .sources()
            .some(
              (s) =>
                s.accountScope === source.accountScope &&
                s.courseId === source.courseId &&
                s.scope === "course",
            ) ||
          !included(job.parent) ||
          // fix/sync-events: per job, the student's current choice (an exclusion mid-run holds).
          store
            .courseOverrides()
            .find((o) => o.accountScope === source.accountScope && o.courseId === source.courseId)
            ?.included === false
        )
          continue;
        const latest = prior && store.resource(prior.id);
        if (prior && (!latest || latest.deleted || latest.contentHash !== prior.contentHash))
          continue;
        const input = resourceInputSchema.parse({
          ...(prior ? inputResource(prior) : {}),
          externalId: prior?.externalId ?? page.page_id,
          kind: "material",
          courseId: source.courseId,
          courseName: job.parent.courseName,
          url: job.url,
          title: page.title,
          updatedAt: page.updated_at,
          ...canvasContent(page.body, job.url),
        });
        save({
          source,
          observedAt: now().toISOString(),
          complete: true,
          status: "ok",
          resources: [input],
        });
        // Retain parent account context while extending the bounded frontier.
        for (const link of input.links ?? [])
          enqueue(
            typeof link === "string" ? link : link.url,
            job.parent,
            job.depth + 1,
          );
      } catch (error) {
        signal.throwIfAborted();
        if (
          !store
            .sources()
            .some(
              (s) =>
                s.accountScope === source.accountScope &&
                s.courseId === source.courseId &&
                s.scope === "course",
            )
        )
          continue;
        save({
          source,
          observedAt: now().toISOString(),
          complete: false,
          status: http.needsSignIn
            ? "needs_sign_in"
            : error instanceof CanvasFailure && error.status === "inaccessible"
              ? "inaccessible"
              : "partial",
          resources: [],
        });
      }
    }
    if (http.needsSignIn) markExpired();
    return http.needsSignIn;
  }
