      const included = new Set(
        courses().map(({ resource }) => resource.courseId),
      );
      // fix/sync-events: one the stored inventory doesn't know at all (not merely excluded) means
      // the inventory changed: the coordinator escalates to a full read.
      const known = new Set(
        store
          .sources()
          .filter((s) => s.kind === "canvas" && s.scope === "course")
          .map((s) => s.courseId),
      );
      if (courseIds.some((id) => id !== "account" && !known.has(id)))
        return { needsSignIn: false, complete: true, inventoryChanged: true };
      const read = courseIds.filter((id) => included.has(id));
      if (!read.length) return { needsSignIn: false, complete: true };
      return canvasRead(new Set(read), signal);
    },
    // end owner: T33
    external,
    record(run) {
      recordRun(run);
    },
    // fix/sync-events: baselines survive a relaunch; hashes and times only, beside the database.
    fingerprint: () =>
      hashCanvas(
        [
          store.generation?.() ?? "",
          ...store
            .sources()
            .filter((s) => s.kind === "canvas" && s.scope === "course")
            .map((s) => s.id)
            .sort(),
        ].join("|"),
      ),
    manual: (signal) => manualCheck(signal),
    persist: {
      load: () => JSON.parse(readFileSync(join(host.directory, "canvas-refresh.json"), "utf8")),
      save: (snapshot) =>
        writeFileSync(join(host.directory, "canvas-refresh.json"), JSON.stringify(snapshot), { mode: 0o600 }),
    },
  });
  /**
   * fix/current-courses-only. The student's UW current enrollment (Course Search & Enroll), when
   * planning has read it: a Canvas course matches an enrolled class by subject and catalog number
   * (and section, when both name one). Code only; nothing here reaches AI, Jev or MCP. Without
   * planning data, Canvas's own signals decide alone.
   */
  /** The enrollment matcher for the connector; authoritative whenever the read found this term's classes. */
  function enrollmentOptions() {
    const enrolledThisTerm = planningEnrollment();
    return enrolledThisTerm ? { enrolledThisTerm, enrollmentAuthoritative: true } : {};
  }
  function planningEnrollment(): ((course: SelectableCanvasCourse) => boolean) | undefined {
    const enrollment = currentEnrollment(store.planningRecords?.() ?? [], now());
    return enrollment ? (course) => !!enrollment.match(course) : undefined;
  }
  /**
   * fix/current-courses-only. Canvas's nameless `{id, access_restricted_by_date}` rows are no
   * longer stored; a workspace that stored one before is repaired without losing history:
   * - a course whose row an earlier version named (it became date-restricted and the nameless
   *   observation overwrote its name) gets that named version back, marked restricted and not
   *   included
   * - only a row that never had a name and has no other source for its course is retired
   * - anything else is left as it is (hidden from the course list, never deleted)
   */
  const NAMELESS = /^Course \d+ \(name unavailable\)$/;
  function repairNamelessCourses() {
    const sources = store.sources();
    for (const r of store.resources()) {
      if (r.kind !== "course" || r.deleted || !NAMELESS.test(r.courseName)) continue;
      const source = sources.find((s) => s.id === r.sourceId);
      if (!source || source.kind !== "canvas" || source.scope !== "course") continue;
      const named = store.resourceHistory?.(r.id).find((v) => v.resource.courseName && !NAMELESS.test(v.resource.courseName));
      if (named) {
        const restored = resourceInputSchema.parse({
          ...named.resource,
          course: {
            ...named.resource.course,
            accessRestricted: true,
            accessState: "date_restricted",
            selection: {
              score: named.resource.course?.selection?.score ?? 0,
              included: false,
              reasons: ["Canvas now restricts this course by date; kept with its last known name"],
            },
          },
        });
        const { id, label, kind, accountScope, courseId, scope } = source;
        save({
          source: { id, label: `${restored.courseName.slice(0, 145)} · course`.slice(0, 200) || label, kind, accountScope, courseId, scope },
          observedAt: now().toISOString(),
          status: "ok",
          complete: true,
          resources: [restored],
          diagnostics: [{ code: "restored_named_course_version", path: [], severity: "warning" }],
        });
        continue;
      }
      const siblings = sources.some(
        (s) => s.id !== source.id && s.accountScope === source.accountScope && s.courseId === source.courseId,
      );
      if (!siblings) store.removeSource(source.id);
    }
  }
  /**
   * fix/current-courses-only. Discovery before the first full read: the profile and the course
   * lists only, so onboarding can show the courses and the student can choose. Background
   * reads hold until the student starts the sync (the next manual run).
   */
  const holdForChoice = (value: boolean) => {
    const settings = store.ingestionSettings();
    if (settings.awaitingCourseChoice !== value) store.setIngestionSettings({ ...settings, awaitingCourseChoice: value });
  };
  /** The listable courses (onboarding's chooser rule): named, not past. */
  const choiceCount = () =>
    courseChoices({
      sources: store.sources(),
      resources: store.resources(),
      courseOverrides: store.courseOverrides(),
    } as unknown as Parameters<typeof courseChoices>[0]).length;
  async function discover(signal = new AbortController().signal) {
    // Held before anything is read, and any run already under way (a background tick, the
    // 30-second timer, a reconnect) is cancelled first, so no unconfirmed course is read.
    holdForChoice(true);
    if (reconnectBarrier) await reconnectBarrier;
    await coordinator.cancelAndWait();
    const s = store.ingestionSettings();
    for await (const batch of canvasConnector({
      fetch: host.canvasFetch,
      metadataConcurrency: s.metadataConcurrency,
      selectedTerm: s.selectedTerm,
      courseOverrides: store.courseOverrides(),
      knownResources: store.resources(),
      ...enrollmentOptions(),
      now,
      catalogOnly: true,
    }).pull(signal))
      save(batch);
    repairNamelessCourses();
    // Nothing to choose from: no hold (the next sync reads nothing unconfirmed anyway).
    if (!choiceCount()) holdForChoice(false);
  }
  /** "Start syncing": the student confirmed the course choice. The only way the hold is released. */
  function confirmCourses() {
    holdForChoice(false);
    return tick("manual");
  }
  /**
   * fix/sync-events. What a manual refresh reads besides the probes, for the changes they can't
   * see: the course lists (with each current course's syllabus body) and every included course's
   * assignment list (one request each: a due date moved outside the to-do window). A course the
   * lists add is returned for a course read.
   */
  async function manualCheck(signal: AbortSignal) {
    const before = new Set(courses().map(({ resource }) => resource.courseId));
    const s = store.ingestionSettings();
    let needsSignIn = false;
    for await (const batch of canvasConnector({
      fetch: host.canvasFetch,
      metadataConcurrency: s.metadataConcurrency,
      scheduler: scheduler(),
      selectedTerm: s.selectedTerm,
      courseOverrides: store.courseOverrides(),
      knownResources: store.resources(),
      ...enrollmentOptions(),
      now,
      catalogOnly: true,
      syllabusFromCatalog: true,
    }).pull(signal)) {
      save(batch);
      needsSignIn ||= batch.status === "needs_sign_in" && !batch.source.courseId;
    }
    if (needsSignIn) return { needsSignIn: true };
    const current = courses();
    const added = current.map(({ resource }) => resource.courseId).filter((id) => !before.has(id));
    const http = new CanvasHttp({ fetch: host.canvasFetch, metadataConcurrency: s.metadataConcurrency, scheduler: scheduler() });
    const known = store.resources();
    let complete = true;
    for (const { resource, source } of current) {
      if (added.includes(resource.courseId)) continue; // the course read covers it
      const result = await canvasTargetedRead(
        http,
        { accountScope: source.accountScope, id: resource.courseId, name: resource.courseName },
        [{ kind: "assignment" }],
        known.filter((r) => r.courseId === resource.courseId),
        { now, collectComments: s.collectComments, signal },
      );
      for (const batch of result.batches) save(batch);
      if (result.needsSignIn) return { needsSignIn: true };
      complete &&= result.complete;
    }
    return { needsSignIn: false, complete, courses: added };
  }
  // owner: T33. One Canvas read: every included course (full), or only the given ones (warm).
  async function canvasRead(
    only: Set<string> | undefined,
    signal: AbortSignal,
  ) {
    let needsSignIn = false;
    const signInCourses = new Set<string>(); // owner: acquisition (RC4)
    let accountSignIn = false;
    const s = store.ingestionSettings();
    for await (const batch of canvasConnector({
      onIdentity: (identity) => {
        if (!signal.aborted && !reconnecting) store.recordAutoIdentity(identity);
      },
      fetch: host.canvasFetch,
      metadataConcurrency: s.metadataConcurrency,
      scheduler: scheduler(), // owner: T17
      collectComments: s.collectComments,
      selectedTerm: s.selectedTerm,
      courseOverrides: store.courseOverrides(),
      knownResources: store.resources(),
      ...enrollmentOptions(), // fix/current-courses-only
      pageReadThisRun: (url) => [...observedPages].some((key) => key.endsWith(`:${url}`)), // fix/sync-events
      moduleRun,
      onModuleRun: (run) => {
        if (!signal.aborted && !reconnecting) moduleRun = run;
      },
      now,
      ...(only ? { onlyCourses: [...only] } : {}), // owner: T33
      onCalendarFeed: (feed) =>
        host
          .secrets(
            "set",
            `calendar:${feed.accountScope}:${feed.courseId}`,
            feed.url,
          )
          .then(() => {}),
    }).pull(signal)) {
      save(batch);
      needsSignIn ||= batch.status === "needs_sign_in";
      // owner: acquisition (RC4): a sign-in state on one course's source no longer skips the
      // documents of every other course; only an account-level one (no course) does.
      if (batch.status === "needs_sign_in") {
        if (batch.source.courseId) signInCourses.add(batch.source.courseId);
        else accountSignIn = true;
      }
    }
    repairNamelessCourses(); // fix/current-courses-only
    if (needsSignIn && accountSignIn) markExpired();
    else {
      // documents() stops at its first sign-in answer (one request) if the session is gone.
      const documentsSignIn = await documents(signal, only, signInCourses);
      if (!documentsSignIn) startOcr(); // owner: acquisition: background, never awaited
      if (!needsSignIn && !documentsSignIn) await inventory(only, signal); // owner: T05b (D32, D41)
      if (needsSignIn && !documentsSignIn) markExpired();
      needsSignIn ||= documentsSignIn;
    }
    // end owner: acquisition
    await feeds(signal);
    return {
      needsSignIn,
      complete: !hasIncompleteRead(),
      retryNeeded: store
        .sources()
        .some(
          (s) =>
            sourceIds.has(s.id) &&
            !["ok", "inaccessible", "not_published"].includes(s.status),
        ),
    };
  }
  // end owner: T33
  function recordRun(
    run: Parameters<
      Parameters<typeof createRefreshCoordinator>[0]["record"]
    >[0],
  ) {
    store.addSyncRun({
      id: randomUUID(),
      startedAt: run.startedAt,
      finishedAt: run.finishedAt,
      action: run.trigger,
      status: run.needsSignIn
        ? "needs_sign_in"
        : run.action === "failed"
          ? "error"
          : hasIncompleteRead()
            ? "partial"
            : run.action === "unchanged"
              ? "unchanged"
              : "ok",
      sourceCount: sourceIds.size,
      stats: {
        durationMs: Date.parse(run.finishedAt) - Date.parse(run.startedAt),
        firstValueMs,
        nextWeekInstructionsMs,
        rateLimitRemaining,
        requestCost,
      },
      diagnostics: [],
    });
  }
  function markExpired() {
    for (const s of store.sources().filter((s) => s.kind === "canvas")) {
      const { id, label, kind, accountScope, courseId, scope } = s;
      save({
        source: { id, label, kind, accountScope, courseId, scope },
        observedAt: now().toISOString(),
        status: "needs_sign_in",
        complete: false,
        resources: [],
      });
    }
  }
  // owner: T17. One sync after sign-in. Main's `reconnected` only re-arms the coordinator; the
  // renderer's sync call (startSignIn) owns the read. If a background tick got to it first, a
  // manual call while that read runs joins it (the coordinator's own guard), and one that arrives
  // within a minute after it finished is answered by it instead of reading everything again.
  let signInPending = false,
    signInRead:
      | { at: number; run: Awaited<ReturnType<typeof coordinator.tick>> }
      | undefined;
  let reconnectBarrier: Promise<void> | undefined;
  let sessionGeneration = 0;
  function tick(
    trigger: "manual" | "background" = "background",
  ): ReturnType<typeof coordinator.tick> {
    if (reconnectBarrier) return reconnectBarrier.then(() => tick(trigger));
    // fix/current-courses-only: while the student chooses courses, only their own start reads.
    // While the student chooses, a background tick reads nothing and a manual one (the launch
    // sign-in, a refresh) refreshes the course list only. confirmCourses() releases the hold.
    if (store.ingestionSettings().awaitingCourseChoice)
      return trigger === "manual" ? discover().then(() => undefined) : Promise.resolve(undefined);
    const generation = sessionGeneration;
    if (
      trigger === "manual" &&
      signInRead &&
      now().getTime() - signInRead.at < 60_000
    ) {
      const { run } = signInRead;
      signInRead = undefined;
      return Promise.resolve(run);
    }
    const running = coordinator.tick(trigger);
    if (signInPending) {
      signInPending = false;
      const claimed = trigger;
      void running.then((run) => {
        if (generation !== sessionGeneration) return;
        if (run?.action === "refreshed" && !run.needsSignIn) {
          if (claimed === "background")
            signInRead = { at: now().getTime(), run };
        } else signInPending = true; // nothing was read: the next tick still owns the sign-in sync
      });
    }
    return running;
  }
  // end owner: T17
  return {
    ...coordinator,
    tick, // owner: T17
    markExpired,
    discover, // fix/current-courses-only
    /** fix/sync-events. The student changed a course's inclusion: it is probed afresh. */
    forget: (courseId: string) => coordinator.forget(courseId),
    /** fix/sync-events. Delete local data: the saved refresh baselines go too. */
    purged() {
      coordinator.purged();
      rmSync(join(host.directory, "canvas-refresh.json"), { force: true });
    },
    confirmCourses, // fix/current-courses-only
    // owner: T05b
    reconnected() {
      coordinator.invalidateSaved(); // fix/sync-events: before the running read is cancelled
      sessionGeneration++;
      reconnecting = true;
      recheckAll = true;
      signInPending = true;
      signInRead = undefined;
      if (moduleRun) moduleRun.invalidated = true;
      moduleRun = undefined;
      runScheduler = undefined;
      const barrier = coordinator.cancelAndWait().then(() => {
        if (reconnectBarrier !== barrier) return;
        coordinator.reconnected();
        reconnecting = false;
        reconnectBarrier = undefined;
      });
      reconnectBarrier = barrier;
      return barrier;
    },
    readLinked, // owner: site-recipes
    /** owner: site-recipes. The core's `ui_event` seam: opening an item reads its `read_once` links. */
    onUiEvent: async (event: { kind: string; subject: string }) => {
      if (event.kind === "open") await readLinked(event.subject).catch(() => {});
    },
    spaces: () => [...spaces.values()].flat(),
    accessSummary: () => accessSummary([...spaces.values()].flat()),
    recheckAccess,
    moduleHashes: () => new Map(moduleHashes),
    probeRequests: () => probeRequests, // owner: T33
    documentRun: () => ({ ...lastDocumentRun, pool: extractPool?.stats(), threaded: extractPool?.threaded ?? false }), // owner: acquisition
    closeExtraction: () => extractPool?.close(), // owner: acquisition
    // end owner: T05b
  };
}

