// ---------- Inventory and access (D32, D40, D41) ----------
export const spaceRoutes = ["api", "public", "uw-session", "canvas-session", "own-login", "lti"] as const;
export const readStates = ["found", "read", "needs-signin", "blocked", "failed", "skipped"] as const;
