}
/** One course's indicator chip (D41): counts by access state. */
export interface CourseAccessSummary {
  accountScope: string;
  courseId: string;
  total: number;
  readable: number;
  needsUwSignin: number;
  needsOwnLogin: number;
  linkOnly: number;
