        const live = prepare("SELECT content_hash FROM resources WHERE id = ? AND deleted = 0").get(fromResourceId);
        if (!live) return { ok: false, errors: ["The resource is missing or deleted."] };
        if (String(live.content_hash) !== inputHash)
